#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ContextMenu's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/context_menu.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The menu's width in logical units at text scale 1, 120 to 1024 (default 120): the narrowest a panel is; a panel is as wide as its widest row needs. A change closes an open menu. A width outside that range, or not finite, throws std::invalid_argument; a disposed menu throws std::logic_error.
template <typename Declaring>
struct ContextMenuPreferredWidthCapability {
    PropertyCell<double, ContextMenuPreferredWidthCapability<Declaring>> preferred_width{120.0};

    static void assign(ContextMenuPreferredWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.preferred_width), incoming);
        if (!capability.preferred_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.preferred_width));
    }
};

// Every ContextMenu capability, in the order the declaring class takes them.
template <typename Declaring>
struct ContextMenuCapabilities : public ContextMenuPreferredWidthCapability<Declaring> {};

} // namespace gui_forms
